```go
func LoggingInterceptor(logger *log.Logger) grpc.UnaryServerInterceptor {
    return func(
        ctx context.Context,
        req interface{},
        info *grpc.UnaryServerInfo,
        handler grpc.UnaryHandler,
    ) (interface{}, error) {
        start := time.Now()

        resp, err := handler(ctx, req)

        code := codes.OK
        if err != nil {
            code = status.Code(err)
        }
        logger.Printf("method=%s duration=%s code=%s", info.FullMethod, time.Since(start), code)

        return resp, err
    }
}

// registered with:
// grpc.NewServer(grpc.UnaryInterceptor(LoggingInterceptor(logger)))
```

An interceptor wraps every unary RPC on the server, so this is the right layer for cross-cutting concerns like logging, auth, or metrics rather than repeating the same code in every handler. Calling `handler(ctx, req)` first and logging afterward means the logged duration and status code reflect the actual outcome of the wrapped call, including any error it returned.

`defer` schedules a call to run when the enclosing function returns, which makes it ideal for cleanup that must happen regardless of which return path is taken: closing files, unlocking mutexes, closing HTTP response bodies. Arguments to a deferred call are evaluated immediately, not when the deferred call runs, which trips people up in loops:

```go
// bug: every deferred call closes the SAME (last) file
for _, name := range names {
    f, _ := os.Open(name)
    defer f.Close()
}

// fix: wrap the loop body so defer fires each iteration
for _, name := range names {
    func() {
        f, _ := os.Open(name)
        defer f.Close()
        process(f)
    }()
}
```

Use struct tags to control the JSON field name, omit-empty behavior, and whether a field is excluded entirely:

```go
type User struct {
    ID        int       `json:"id"`
    Name      string    `json:"name"`
    Email     string    `json:"email,omitempty"`
    Password  string    `json:"-"`
    CreatedAt time.Time `json:"created_at"`
}

data, err := json.Marshal(user)
if err != nil {
    return fmt.Errorf("marshaling user: %w", err)
}

var u User
if err := json.Unmarshal(data, &u); err != nil {
    return fmt.Errorf("unmarshaling user: %w", err)
}
```
`omitempty` drops the field from the output when it holds its zero value; `json:"-"` always excludes the field, which is how you keep a field like `Password` out of any API response built from the struct.

```go
func (s *reportServer) StreamOrders(req *pb.StreamOrdersRequest, stream pb.ReportService_StreamOrdersServer) error {
    rows, err := s.db.QueryContext(stream.Context(),
        "SELECT id, total FROM orders WHERE user_id = ?", req.GetUserId())
    if err != nil {
        return status.Errorf(codes.Internal, "querying orders: %v", err)
    }
    defer rows.Close()

    for rows.Next() {
        var id int64
        var total float64
        if err := rows.Scan(&id, &total); err != nil {
            return status.Errorf(codes.Internal, "scanning row: %v", err)
        }

        if err := stream.Send(&pb.Order{Id: id, Total: total}); err != nil {
            return status.Errorf(codes.Internal, "sending order: %v", err)
        }
    }

    return rows.Err()
}
```

Streaming rows through `stream.Send` one at a time, instead of collecting them into a slice first and sending a single large response, keeps memory usage flat regardless of result size and lets the client start processing before the query has even finished. Using `stream.Context()` for the query ties it to the RPC's lifetime — if the client disconnects mid-stream, the query gets cancelled instead of running to completion for nothing.

```go
func Recover(next http.Handler) http.Handler {
    return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
        defer func() {
            if err := recover(); err != nil {
                log.Printf("panic recovered: %v\n%s", err, debug.Stack())
                w.WriteHeader(http.StatusInternalServerError)
                w.Write([]byte("internal server error"))
            }
        }()
        next.ServeHTTP(w, r)
    })
}
```

Placing `Recover` as the outermost middleware ensures a panic in any handler
downstream — including other middleware — is caught before it takes down the
whole server process, since an unrecovered panic in a goroutine (which each
HTTP request runs in) crashes the program.

```go
package store

import (
    "errors"
    "sync"
)

// Product represents a product record.
type Product struct {
    ID int
    Name string
    PriceCents int64
}

var ErrProductNotFound = errors.New("product: not found")

// ProductStore defines persistence operations for Product.
// Defined at the point of use so callers can supply an in-memory,
// SQL-backed, or mock implementation interchangeably.
type ProductStore interface {
    Get(id int) (*Product, error)
    Create(name string, pricecents int64) (*Product, error)
    Delete(id int) error
}

// MemProductStore is a concurrency-safe in-memory ProductStore, useful for
// tests and local development.
type MemProductStore struct {
    mu     sync.RWMutex
    nextID int
    data   map[int]*Product
}

func NewMemProductStore() *MemProductStore {
    return &MemProductStore{
        nextID: 1,
        data:   make(map[int]*Product),
    }
}

func (s *MemProductStore) Get(id int) (*Product, error) {
    s.mu.RLock()
    defer s.mu.RUnlock()

    v, ok := s.data[id]
    if !ok {
        return nil, ErrProductNotFound
    }
    // return a copy so callers can't mutate our internal state
    cp := *v
    return &cp, nil
}

func (s *MemProductStore) Create(name string, pricecents int64) (*Product, error) {
    s.mu.Lock()
    defer s.mu.Unlock()

    v := &Product{
        ID: s.nextID,
        Name: name,
        PriceCents: pricecents,
    }
    s.data[v.ID] = v
    s.nextID++
    return v, nil
}

func (s *MemProductStore) Delete(id int) error {
    s.mu.Lock()
    defer s.mu.Unlock()

    if _, ok := s.data[id]; !ok {
        return ErrProductNotFound
    }
    delete(s.data, id)
    return nil
}

var _ ProductStore = (*MemProductStore)(nil)
```

Define a slice of struct literals, one per test case, with fields for input, expected output, and a descriptive name, then loop over it calling `t.Run` per case so failures report which case failed:

```go
func TestAdd(t *testing.T) {
    tests := []struct {
        name     string
        a, b     int
        want     int
    }{
        {name: "positives", a: 2, b: 3, want: 5},
        {name: "negative", a: -1, b: 1, want: 0},
        {name: "zero", a: 0, b: 0, want: 0},
    }

    for _, tt := range tests {
        t.Run(tt.name, func(t *testing.T) {
            got := Add(tt.a, tt.b)
            if got != tt.want {
                t.Errorf("Add(%d, %d) = %d, want %d", tt.a, tt.b, got, tt.want)
            }
        })
    }
}
```
This scales cleanly as cases are added and gives per-case pass/fail output under `go test -v`.

```go
type Broadcaster[T any] struct {
    mu   sync.Mutex
    subs map[chan T]struct{}
}

func NewBroadcaster[T any]() *Broadcaster[T] {
    return &Broadcaster[T]{subs: make(map[chan T]struct{})}
}

func (b *Broadcaster[T]) Subscribe() (<-chan T, func()) {
    ch := make(chan T, 1)

    b.mu.Lock()
    b.subs[ch] = struct{}{}
    b.mu.Unlock()

    unsubscribe := func() {
        b.mu.Lock()
        defer b.mu.Unlock()
        if _, ok := b.subs[ch]; ok {
            delete(b.subs, ch)
            close(ch)
        }
    }
    return ch, unsubscribe
}

func (b *Broadcaster[T]) Publish(msg T) {
    b.mu.Lock()
    defer b.mu.Unlock()

    for ch := range b.subs {
        select {
        case ch <- msg:
        default:
            // slow subscriber: drop the message rather than block Publish
        }
    }
}
```

`Publish` uses a non-blocking send (`select` with a `default` case) so one slow or stalled subscriber can't block delivery to everyone else — the trade-off is that a subscriber whose buffer is full silently misses messages, which is appropriate for something like a live metrics feed but wrong for anything that needs guaranteed delivery. Returning an `unsubscribe` closure alongside the channel, rather than a separate `Unsubscribe(ch)` method, keeps ownership of the channel scoped to whoever subscribed.

```go
func withRetry[T any](ctx context.Context, maxAttempts int, fn func() (T, error)) (T, error) {
    var zero T
    backoff := 100 * time.Millisecond

    for attempt := 1; attempt <= maxAttempts; attempt++ {
        result, err := fn()
        if err == nil {
            return result, nil
        }

        if attempt == maxAttempts {
            return zero, fmt.Errorf("after %d attempts: %w", attempt, err)
        }

        select {
        case <-time.After(backoff):
            backoff *= 2
        case <-ctx.Done():
            return zero, ctx.Err()
        }
    }
    return zero, nil // unreachable
}
```

