    s.mu.Lock()
    defer s.mu.Unlock()

    if _, ok := s.data[id]; !ok {
        return ErrOrderNotFound
    }
    delete(s.data, id)
    return nil
}

var _ OrderStore = (*MemOrderStore)(nil)
