type Node[T cmp.Ordered] struct {
    Value T
    Left  *Node[T]
    Right *Node[T]
}

func (n *Node[T]) Insert(v T) *Node[T] {
    if n == nil {
        return &Node[T]{Value: v}
    }
    if v < n.Value {
        n.Left = n.Left.Insert(v)
    } else if v > n.Value {
        n.Right = n.Right.Insert(v)
    }
    return n
}

func (n *Node[T]) InOrder() []T {
    if n == nil {
        return nil
    }
    var result []T
    result = append(result, n.Left.InOrder()...)
    result = append(result, n.Value)
    result = append(result, n.Right.InOrder()...)
    return result
}
```

The `cmp.Ordered` constraint (from the standard library's `cmp` package, Go 1.21+) matches any type supporting `<`, `>`, `==` — ints, floats, strings — so this one implementation works for a `Node[int]`, `Node[string]`, or `Node[float64]` without duplication. Methods work on a nil `*Node[T]` receiver deliberately (`if n == nil`), which is what lets both `Insert` and `InOrder` handle an empty subtree without a separate nil check at every call site.

