```go
package store

import (
    "errors"
    "sync"
)

// Article represents a article record.
type Article struct {
    ID int
    Title string
    Body string
}

var ErrArticleNotFound = errors.New("article: not found")

// ArticleStore defines persistence operations for Article.
// Defined at the point of use so callers can supply an in-memory,
// SQL-backed, or mock implementation interchangeably.
type ArticleStore interface {
    Get(id int) (*Article, error)
    Create(title string, body string) (*Article, error)
    Delete(id int) error
}

// MemArticleStore is a concurrency-safe in-memory ArticleStore, useful for
// tests and local development.
type MemArticleStore struct {
    mu     sync.RWMutex
    nextID int
    data   map[int]*Article
}

func NewMemArticleStore() *MemArticleStore {
    return &MemArticleStore{
        nextID: 1,
        data:   make(map[int]*Article),
    }
}

func (s *MemArticleStore) Get(id int) (*Article, error) {
    s.mu.RLock()
    defer s.mu.RUnlock()

    v, ok := s.data[id]
    if !ok {
        return nil, ErrArticleNotFound
    }
    // return a copy so callers can't mutate our internal state
    cp := *v
    return &cp, nil
}

func (s *MemArticleStore) Create(title string, body string) (*Article, error) {
    s.mu.Lock()
    defer s.mu.Unlock()

    v := &Article{
        ID: s.nextID,
        Title: title,
        Body: body,
    }
    s.data[v.ID] = v
    s.nextID++
    return v, nil
}

func (s *MemArticleStore) Delete(id int) error {
    s.mu.Lock()
    defer s.mu.Unlock()

    if _, ok := s.data[id]; !ok {
        return ErrArticleNotFound
    }
    delete(s.data, id)
    return nil
}

var _ ArticleStore = (*MemArticleStore)(nil)
```

