func generator[T any](values ...T) <-chan T {
    out := make(chan T)
    go func() {
        defer close(out)
        for _, v := range values {
            out <- v
        }
    }()
    return out
}

func stage[In, Out any](in <-chan In, f func(In) Out) <-chan Out {
    out := make(chan Out)
    go func() {
        defer close(out)
        for v := range in {
            out <- f(v)
        }
    }()
    return out
}

// usage: numbers -> doubled -> stringified
func Example() {
    numbers := generator(1, 2, 3, 4, 5)
    doubled := stage(numbers, func(n int) int { return n * 2 })
    strs := stage(doubled, func(n int) string { return fmt.Sprintf("#%d", n) })

    for s := range strs {
        fmt.Println(s)
    }
}
