```go
func resolvePort(flagVal int, envKey, configPath string) int {
    if flagVal != 0 {
        return flagVal
    }
    if v := os.Getenv(envKey); v != "" {
        if n, err := strconv.Atoi(v); err == nil {
            return n
        }
    }
    if data, err := os.ReadFile(configPath); err == nil {
        var cfg struct {
            Port int `json:"port"`
        }
        if json.Unmarshal(data, &cfg) == nil && cfg.Port != 0 {
            return cfg.Port
        }
    }
    return 8080 // hardcoded default
}

func main() {
    portFlag := flag.Int("port", 0, "port to listen on")
    flag.Parse()

    port := resolvePort(*portFlag, "APP_PORT", "config.json")
    fmt.Printf("listening on port %d\n", port)
}
```

Structuring the precedence as a pure function (`resolvePort`) rather than inlining the logic in `main` makes each layer independently testable — you can assert the flag wins over the env var, the env var wins over the file, and the file wins over the default, without spinning up a real process or real files for every case.

