func HumanDuration(d time.Duration) string {
    d = d.Round(time.Second)
    h := d / time.Hour
    d -= h * time.Hour
    m := d / time.Minute
    d -= m * time.Minute
    s := d / time.Second

    var parts []string
    if h > 0 {
        parts = append(parts, fmt.Sprintf("%dh", h))
    }
    if m > 0 || h > 0 {
        parts = append(parts, fmt.Sprintf("%dm", m))
    }
    parts = append(parts, fmt.Sprintf("%ds", s))
    return strings.Join(parts, " ")
}
