func MinMax[T cmp.Ordered](values []T) (min, max T, err error) {
    if len(values) == 0 {
        return min, max, errors.New("MinMax: empty slice")
    }

    min, max = values[0], values[0]
    for _, v := range values[1:] {
        if v < min {
            min = v
        }
        if v > max {
            max = v
        }
    }
    return min, max, nil
}
```

