```go
func GetUserWithRetry(ctx context.Context, client pb.UserServiceClient, id int64) (*pb.User, error) {
    var lastErr error

    for attempt := 0; attempt < 2; attempt++ {
        callCtx, cancel := context.WithTimeout(ctx, 2*time.Second)
        resp, err := client.GetUser(callCtx, &pb.GetUserRequest{Id: id})
        cancel()

        if err == nil {
            return resp.GetUser(), nil
        }

        lastErr = err
        st, ok := status.FromError(err)
        if !ok || !isRetryable(st.Code()) {
            return nil, err
        }
        time.Sleep(200 * time.Millisecond)
    }

    return nil, fmt.Errorf("get user failed after retries: %w", lastErr)
}

func isRetryable(code codes.Code) bool {
    switch code {
    case codes.Unavailable, codes.DeadlineExceeded, codes.ResourceExhausted:
        return true
    default:
        return false
    }
}
```

Only retrying on codes that actually represent transient conditions (`Unavailable`, `DeadlineExceeded`, `ResourceExhausted`) — and not, say, `InvalidArgument` or `NotFound`, which will fail identically on every retry — avoids wasting a retry budget on requests that are never going to succeed.

```go
type Number interface {
    ~int | ~int64 | ~float32 | ~float64
}

func Sum[T Number](values []T) T {
    var total T
    for _, v := range values {
        total += v
    }
    return total
}

// Sum([]int{1, 2, 3}) == 6
// Sum([]float64{1.5, 2.5}) == 4.0
```
The `~int` form matches not just `int` but any type whose underlying type is `int`, which lets the constraint also accept named types like `type Meters int`. The standard library's `constraints` and `cmp` packages provide common constraints like this so you don't need to redefine them per project.

```go
type QueryBuilder struct {
    table      string
    columns    []string
    conditions []string
    args       []any
    limit      int
}

func NewQuery(table string) *QueryBuilder {
    return &QueryBuilder{table: table, columns: []string{"*"}}
}

func (q *QueryBuilder) Select(cols ...string) *QueryBuilder {
    q.columns = cols
    return q
}

func (q *QueryBuilder) Where(cond string, arg any) *QueryBuilder {
    q.conditions = append(q.conditions, cond)
    q.args = append(q.args, arg)
    return q
}

func (q *QueryBuilder) Limit(n int) *QueryBuilder {
    q.limit = n
    return q
}

func (q *QueryBuilder) Build() (string, []any) {
    query := fmt.Sprintf("SELECT %s FROM %s", strings.Join(q.columns, ", "), q.table)
    if len(q.conditions) > 0 {
        query += " WHERE " + strings.Join(q.conditions, " AND ")
    }
    if q.limit > 0 {
        query += fmt.Sprintf(" LIMIT %d", q.limit)
    }
    return query, q.args
}

// usage:
// query, args := NewQuery("users").
//     Select("id", "name").
//     Where("age > ?", 18).
//     Limit(10).
//     Build()
```

Each method returns `*QueryBuilder` so calls chain fluently. Keep `Build()` as the single terminal method that produces the final value — everything before it should only accumulate state, never perform I/O, so the builder stays easy to test in isolation from the database.

```go
func SafeDivide(a, b float64) (float64, error) {
    if b == 0 {
        return 0, errors.New("division by zero")
    }
    return a / b, nil
}
```

Go has no function overloading and no default parameter values, so a constructor with several optional settings either needs a large parameter list (error-prone at call sites, especially with several same-typed params) or an options pattern. Functional options keep the required parameters explicit while making every optional setting self-documenting at the call site and independently addable later without breaking existing callers:

```go
type Server struct {
    addr    string
    timeout time.Duration
    logger  *log.Logger
}

type Option func(*Server)

func WithTimeout(d time.Duration) Option {
    return func(s *Server) { s.timeout = d }
}

func WithLogger(l *log.Logger) Option {
    return func(s *Server) { s.logger = l }
}

func NewServer(addr string, opts ...Option) *Server {
    s := &Server{addr: addr, timeout: 30 * time.Second}
    for _, opt := range opts {
        opt(s)
    }
    return s
}
```

```go
func FetchFastest(ctx context.Context, sources ...func(context.Context) (string, error)) (string, error) {
    type result struct {
        val string
        err error
    }

    ctx, cancel := context.WithCancel(ctx)
    defer cancel()

    ch := make(chan result, len(sources))
    for _, src := range sources {
        src := src
        go func() {
            val, err := src(ctx)
            select {
            case ch <- result{val, err}:
            case <-ctx.Done():
            }
        }()
    }

    for range sources {
        r := <-ch
        if r.err == nil {
            return r.val, nil // cancel() (deferred) stops the other goroutines
        }
    }
    return "", fmt.Errorf("all sources failed")
}
```

Cancelling the shared `ctx` as soon as one source succeeds signals the other in-flight goroutines to stop early if they're honoring `ctx.Done()` internally (for example an HTTP call using this context). The buffered channel (`len(sources)`) means a slower goroutine's send never blocks forever even after the function has already returned.

