```go
type Semaphore struct {
    ch chan struct{}
}

func NewSemaphore(max int) *Semaphore {
    return &Semaphore{ch: make(chan struct{}, max)}
}

func (s *Semaphore) Acquire(ctx context.Context) error {
    select {
    case s.ch <- struct{}{}:
        return nil
    case <-ctx.Done():
        return ctx.Err()
    }
}

func (s *Semaphore) Release() {
    <-s.ch
}

// usage:
func downloadAll(ctx context.Context, urls []string) error {
    sem := NewSemaphore(5)
    var wg sync.WaitGroup
    errCh := make(chan error, len(urls))

    for _, url := range urls {
        url := url
        if err := sem.Acquire(ctx); err != nil {
            return err
        }
        wg.Add(1)
        go func() {
            defer wg.Done()
            defer sem.Release()
            if err := download(ctx, url); err != nil {
                errCh <- err
            }
        }()
    }

    wg.Wait()
    close(errCh)
    for err := range errCh {
        return err // return the first error encountered
    }
    return nil
}
```

A buffered channel of capacity `max` naturally acts as a counting semaphore: a send succeeds only while there's spare buffer space, so the (max+1)-th concurrent `Acquire` blocks until some earlier goroutine calls `Release` (a receive). Wrapping the send in a `select` with `ctx.Done()` means a cancelled context unblocks a goroutine stuck waiting for a slot, instead of leaking it forever.

