    ID        int       `json:"id"`
    Name      string    `json:"name"`
    Email     string    `json:"email,omitempty"`
    Password  string    `json:"-"`
    CreatedAt time.Time `json:"created_at"`
}

data, err := json.Marshal(user)
if err != nil {
    return fmt.Errorf("marshaling user: %w", err)
}

var u User
if err := json.Unmarshal(data, &u); err != nil {
    return fmt.Errorf("unmarshaling user: %w", err)
}
```
`omitempty` drops the field from the output when it holds its zero value; `json:"-"` always excludes the field, which is how you keep a field like `Password` out of any API response built from the struct.

