```go
type Stack[T any] struct {
    items []T
}

func (s *Stack[T]) Push(v T) {
    s.items = append(s.items, v)
}

func (s *Stack[T]) Pop() (T, bool) {
    var zero T
    if len(s.items) == 0 {
        return zero, false
    }
    n := len(s.items) - 1
    v := s.items[n]
    s.items = s.items[:n]
    return v, true
}

type Queue[T any] struct {
    items []T
}

func (q *Queue[T]) Enqueue(v T) {
    q.items = append(q.items, v)
}

func (q *Queue[T]) Dequeue() (T, bool) {
    var zero T
    if len(q.items) == 0 {
        return zero, false
    }
    v := q.items[0]
    q.items = q.items[1:]
    return v, true
}
```

`Pop`/`Dequeue` returning `(T, bool)` rather than panicking on empty follows the same convention as a map lookup (`v, ok := m[k]`), so callers check the second value the same way they already would elsewhere in Go. Note `Queue.Dequeue`'s `q.items = q.items[1:]` doesn't shrink the underlying backing array — for a long-running queue with heavy churn, periodically reallocating (or using a ring buffer) avoids unbounded backing-array growth.

