```go
package store

import (
    "errors"
    "sync"
)

// Article represents a article record.
type Article struct {
    ID int
    Title string
    Body string
}

var ErrArticleNotFound = errors.New("article: not found")

// ArticleStore defines persistence operations for Article.
// Defined at the point of use so callers can supply an in-memory,
// SQL-backed, or mock implementation interchangeably.
type ArticleStore interface {
    Get(id int) (*Article, error)
    Create(title string, body string) (*Article, error)
    Delete(id int) error
}

// MemArticleStore is a concurrency-safe in-memory ArticleStore, useful for
// tests and local development.
type MemArticleStore struct {
    mu     sync.RWMutex
    nextID int
    data   map[int]*Article
}

func NewMemArticleStore() *MemArticleStore {
    return &MemArticleStore{
        nextID: 1,
        data:   make(map[int]*Article),
    }
}

func (s *MemArticleStore) Get(id int) (*Article, error) {
    s.mu.RLock()
    defer s.mu.RUnlock()

    v, ok := s.data[id]
    if !ok {
        return nil, ErrArticleNotFound
    }
    // return a copy so callers can't mutate our internal state
    cp := *v
    return &cp, nil
}

func (s *MemArticleStore) Create(title string, body string) (*Article, error) {
    s.mu.Lock()
    defer s.mu.Unlock()

    v := &Article{
        ID: s.nextID,
        Title: title,
        Body: body,
    }
    s.data[v.ID] = v
    s.nextID++
    return v, nil
}

func (s *MemArticleStore) Delete(id int) error {
    s.mu.Lock()
    defer s.mu.Unlock()

    if _, ok := s.data[id]; !ok {
        return ErrArticleNotFound
    }
    delete(s.data, id)
    return nil
}

var _ ArticleStore = (*MemArticleStore)(nil)
```

```go
func generator[T any](values ...T) <-chan T {
    out := make(chan T)
    go func() {
        defer close(out)
        for _, v := range values {
            out <- v
        }
    }()
    return out
}

func stage[In, Out any](in <-chan In, f func(In) Out) <-chan Out {
    out := make(chan Out)
    go func() {
        defer close(out)
        for v := range in {
            out <- f(v)
        }
    }()
    return out
}

// usage: numbers -> doubled -> stringified
func Example() {
    numbers := generator(1, 2, 3, 4, 5)
    doubled := stage(numbers, func(n int) int { return n * 2 })
    strs := stage(doubled, func(n int) string { return fmt.Sprintf("#%d", n) })

    for s := range strs {
        fmt.Println(s)
    }
}
```

Each stage owns closing its own output channel once its input channel is drained and closed, which is what lets the whole pipeline shut down cleanly just by the generator finishing — no explicit coordination needed between stages.

```go
type Scheduler struct {
    cancel context.CancelFunc
    wg     sync.WaitGroup
}

func StartScheduler(ctx context.Context, tasks map[string]func(context.Context)) *Scheduler {
    ctx, cancel := context.WithCancel(ctx)
    s := &Scheduler{cancel: cancel}

    for name, task := range tasks {
        s.wg.Add(1)
        go func(name string, task func(context.Context)) {
            defer s.wg.Done()
            ticker := time.NewTicker(time.Minute)
            defer ticker.Stop()

            for {
                select {
                case <-ctx.Done():
                    return
                case <-ticker.C:
                    task(ctx)
                }
            }
        }(name, task)
    }
    return s
}

func (s *Scheduler) Stop() {
    s.cancel()
    s.wg.Wait() // block until every task goroutine has actually exited
}
```

`Stop` both cancels the shared context and waits on the `WaitGroup`, so callers get a synchronous guarantee that every task has actually stopped running — not just that cancellation was requested — which matters if shutdown needs to happen before, say, closing a database connection those tasks use.

```go
type userServiceServer struct {
    pb.UnimplementedUserServiceServer
    store UserStore
}

func NewUserServiceServer(store UserStore) pb.UserServiceServer {
    return &userServiceServer{store: store}
}

func (s *userServiceServer) GetUser(ctx context.Context, req *pb.GetUserRequest) (*pb.GetUserResponse, error) {
    if req.GetId() <= 0 {
        return nil, status.Error(codes.InvalidArgument, "id must be positive")
    }

    user, err := s.store.Get(int(req.GetId()))
    if err != nil {
        if errors.Is(err, ErrUserNotFound) {
            return nil, status.Errorf(codes.NotFound, "user %d not found", req.GetId())
        }
        return nil, status.Error(codes.Internal, "failed to fetch user")
    }

    return &pb.GetUserResponse{
        User: &pb.User{
            Id:    int64(user.ID),
            Name:  user.Name,
            Email: user.Email,
        },
    }, nil
}
```

Embedding `pb.UnimplementedUserServiceServer` satisfies forward compatibility — if the `.proto` file gains a new RPC method later, this server still compiles (the embedded type provides a default "unimplemented" response) instead of breaking until you implement it. Returning `status.Error`/`status.Errorf` with the right `codes.*` value matters because gRPC clients (and gateways translating to HTTP) branch on that code, not on the error string — an internal-only implementation detail should map to `codes.Internal`, never leak a raw Go error message to the client, which is why the internal error above is logged but replaced with a generic message.

```go
func resolvePort(flagVal int, envKey, configPath string) int {
    if flagVal != 0 {
        return flagVal
    }
    if v := os.Getenv(envKey); v != "" {
        if n, err := strconv.Atoi(v); err == nil {
            return n
        }
    }
    if data, err := os.ReadFile(configPath); err == nil {
        var cfg struct {
            Port int `json:"port"`
        }
        if json.Unmarshal(data, &cfg) == nil && cfg.Port != 0 {
            return cfg.Port
        }
    }
    return 8080 // hardcoded default
}

func main() {
    portFlag := flag.Int("port", 0, "port to listen on")
    flag.Parse()

    port := resolvePort(*portFlag, "APP_PORT", "config.json")
    fmt.Printf("listening on port %d\n", port)
}
```

Structuring the precedence as a pure function (`resolvePort`) rather than inlining the logic in `main` makes each layer independently testable — you can assert the flag wins over the env var, the env var wins over the file, and the file wins over the default, without spinning up a real process or real files for every case.

