func NewMemOrderStore() *MemOrderStore {
    return &MemOrderStore{
        nextID: 1,
        data:   make(map[int]*Order),
    }
}

func (s *MemOrderStore) Get(id int) (*Order, error) {
    s.mu.RLock()
    defer s.mu.RUnlock()

    v, ok := s.data[id]
    if !ok {
        return nil, ErrOrderNotFound
    }
    // return a copy so callers can't mutate our internal state
    cp := *v
    return &cp, nil
}

func (s *MemOrderStore) Create(userid int, total float64) (*Order, error) {
    s.mu.Lock()
    defer s.mu.Unlock()

    v := &Order{
        ID: s.nextID,
        UserID: userid,
        Total: total,
    }
    s.data[v.ID] = v
    s.nextID++
    return v, nil
}

func (s *MemOrderStore) Delete(id int) error {
    s.mu.Lock()
    defer s.mu.Unlock()

    if _, ok := s.data[id]; !ok {
        return ErrOrderNotFound
    }
    delete(s.data, id)
    return nil
}

var _ OrderStore = (*MemOrderStore)(nil)
