func TestParseAge(t *testing.T) {
    tests := []struct {
        name    string
        input   string
        want    int
        wantErr bool
    }{
        {name: "valid", input: "25", want: 25, wantErr: false},
        {name: "negative", input: "-1", want: 0, wantErr: true},
        {name: "not a number", input: "abc", want: 0, wantErr: true},
        {name: "empty", input: "", want: 0, wantErr: true},
    }

    for _, tt := range tests {
        t.Run(tt.name, func(t *testing.T) {
            got, err := ParseAge(tt.input)

            if (err != nil) != tt.wantErr {
                t.Fatalf("ParseAge(%q) error = %v, wantErr %v", tt.input, err, tt.wantErr)
            }
            if err == nil && got != tt.want {
                t.Errorf("ParseAge(%q) = %d, want %d", tt.input, got, tt.want)
            }
        })
    }
}
```

Checking `(err != nil) != tt.wantErr` first, and returning early with `t.Fatalf` on mismatch, avoids a false-positive value assertion running against a zero value produced by an unexpected error path.

Go favors a 'happy path' left-aligned reading style: handle error or exceptional cases early with a guard clause and `return`/`continue`/`break`, then let the normal-case code proceed unindented. This keeps the common path readable top-to-bottom without following an `else` branch mentally. An `if` block that ends in a terminating statement (return, continue, break, panic) should generally omit the following `else` entirely:

```go
// preferred
if err != nil {
    return err
}
doWork()

// avoid
if err != nil {
    return err
} else {
    doWork()
}
```

