import (
    "flag"
    "fmt"
    "io"
    "os"
)

func main() {
    input := flag.String("input", "", "path to input file (required)")
    output := flag.String("output", "", "path to output file (default: stdout)")
    flag.Parse()

    if *input == "" {
        fmt.Fprintln(os.Stderr, "error: -input is required")
        flag.Usage()
        os.Exit(2)
