package store

import (
    "errors"
    "sync"
)

// Product represents a product record.
type Product struct {
    ID int
    Name string
    PriceCents int64
}

var ErrProductNotFound = errors.New("product: not found")

// ProductStore defines persistence operations for Product.
// Defined at the point of use so callers can supply an in-memory,
// SQL-backed, or mock implementation interchangeably.
type ProductStore interface {
    Get(id int) (*Product, error)
    Create(name string, pricecents int64) (*Product, error)
    Delete(id int) error
}

// MemProductStore is a concurrency-safe in-memory ProductStore, useful for
// tests and local development.
type MemProductStore struct {
    mu     sync.RWMutex
    nextID int
    data   map[int]*Product
}

func NewMemProductStore() *MemProductStore {
    return &MemProductStore{
        nextID: 1,
        data:   make(map[int]*Product),
    }
}

func (s *MemProductStore) Get(id int) (*Product, error) {
    s.mu.RLock()
    defer s.mu.RUnlock()

    v, ok := s.data[id]
    if !ok {
        return nil, ErrProductNotFound
    }
    // return a copy so callers can't mutate our internal state
    cp := *v
    return &cp, nil
}

