    // return a copy so callers can't mutate our internal state
    cp := *v
    return &cp, nil
}

func (s *MemSessionStore) Create(token string, userid int) (*Session, error) {
    s.mu.Lock()
    defer s.mu.Unlock()

    v := &Session{
        ID: s.nextID,
        Token: token,
        UserID: userid,
    }
    s.data[v.ID] = v
    s.nextID++
    return v, nil
}

func (s *MemSessionStore) Delete(id int) error {
    s.mu.Lock()
    defer s.mu.Unlock()

    if _, ok := s.data[id]; !ok {
        return ErrSessionNotFound
    }
    delete(s.data, id)
    return nil
}

var _ SessionStore = (*MemSessionStore)(nil)
