type Node[T cmp.Ordered] struct {
    Value T
    Left  *Node[T]
    Right *Node[T]
}

func (n *Node[T]) Insert(v T) *Node[T] {
    if n == nil {
        return &Node[T]{Value: v}
    }
    if v < n.Value {
        n.Left = n.Left.Insert(v)
    } else if v > n.Value {
        n.Right = n.Right.Insert(v)
    }
    return n
}

func (n *Node[T]) InOrder() []T {
    if n == nil {
        return nil
    }
    var result []T
    result = append(result, n.Left.InOrder()...)
    result = append(result, n.Value)
    result = append(result, n.Right.InOrder()...)
    return result
}
```

