func Batch[T any](ctx context.Context, in <-chan T, maxSize int, maxWait time.Duration) <-chan []T {
    out := make(chan []T)

    go func() {
        defer close(out)
        batch := make([]T, 0, maxSize)
        timer := time.NewTimer(maxWait)
        defer timer.Stop()

        flush := func() {
            if len(batch) > 0 {
                out <- batch
                batch = make([]T, 0, maxSize)
            }
        }

        for {
            select {
            case <-ctx.Done():
                flush()
                return
            case v, ok := <-in:
                if !ok {
                    flush()
                    return
                }
                batch = append(batch, v)
                if len(batch) >= maxSize {
                    flush()
                    timer.Reset(maxWait)
                }
            case <-timer.C:
                flush()
                timer.Reset(maxWait)
            }
        }
    }()

    return out
}
```

