func MinMax[T cmp.Ordered](values []T) (min, max T, err error) {
    if len(values) == 0 {
        return min, max, errors.New("MinMax: empty slice")
    }

    min, max = values[0], values[0]
    for _, v := range values[1:] {
        if v < min {
            min = v
        }
        if v > max {
            max = v
        }
    }
    return min, max, nil
}
```

Go 1.21 added built-in `min`/`max` functions for individual values, but they don't operate on a slice — this wraps them into a single-pass slice scan, which is both simpler and roughly twice as fast as calling `slices.Min` and `slices.Max` separately, since each of those walks the whole slice on its own.

